import { ApiError, createApiClient, unwrap } from "@/api/client";
import type { PendingMedia, Queue } from "./queue";

/**
 * Uploads the queue to the server: register → PUT original and thumb → confirm → clean up.
 * Safe to repeat at any point because the id was generated by the phone and the
 * server is idempotent by id.
 */

export type UploaderDeps = {
  queue: Pick<Queue, "pending" | "remove" | "markAttempt" | "markFailed">;
  apiUrl: string;
  getToken: (tripId: string) => Promise<string | null>;
  /** PUT of the file to the signed URL; returns the status. Rejects if there is no network. */
  putFile: (uri: string, url: string, contentType: string) => Promise<number>;
  /** Whether the local file still exists. */
  fileExists: (uri: string) => Promise<boolean>;
  /** Deletes the Documents/pending/<id> folder. */
  removeFiles: (id: string) => Promise<void>;
  /** Called with the trip each time an upload is confirmed (the quota and the total change). */
  onUploaded?: (tripId: string) => void | Promise<void>;
  /** Called with the trip when a photo leaves the queue without being uploaded (permanent failure). */
  onDiscarded?: (tripId: string) => void | Promise<void>;
  now?: () => number;
};

const BACKOFF_BASE_MS = 1000;
const BACKOFF_MAX_MS = 5 * 60 * 1000;

/** Wait after attempt n (1, 2, 4… seconds) up to a cap of 5 minutes. */
export function retryDelay(attempts: number): number {
  return Math.min(BACKOFF_BASE_MS * 2 ** (attempts - 1), BACKOFF_MAX_MS);
}

/** PUT to R2 failure (status 0 = no network). */
class PutFailed extends Error {
  constructor(public readonly status: number) {
    super(`PUT ${status}`);
  }
}

type Phase = "register" | "complete";
type Verdict = { kind: "offline" } | { kind: "retry" } | { kind: "failed"; reason: string };

/** What to do with an error: retry later, stop (no network) or give the item up as lost. */
function classify(error: unknown, phase: Phase): Verdict | null {
  if (error instanceof PutFailed) return error.status === 0 ? { kind: "offline" } : { kind: "retry" };
  if (!(error instanceof ApiError)) return null;
  const { status } = error;
  if (status === 0) return { kind: "offline" };
  if (status >= 500) return { kind: "retry" };
  if (status === 429) return { kind: "failed", reason: "quota" };
  // The reason is the server's message ("El rollo ya se reveló", "Este rollo ya terminó"…).
  if (status === 409) return { kind: "failed", reason: error.message };
  // Confirming a photo the admin deleted returns 404: nothing to retry.
  if (phase === "complete" && status === 404) return { kind: "failed", reason: "deleted" };
  // On confirm, a 4xx may be a file that has not fully arrived: retry.
  if (phase === "complete") return { kind: "retry" };
  return { kind: "failed", reason: error.message || `http_${status}` };
}

export type RunOptions = {
  /**
   * Epoch ms (same clock as `now`). No new item starts once it has passed: the pass ends between
   * items, never in the middle of one, so nothing is left half done. What remains stays pending.
   */
  deadline?: number;
  /**
   * Retry items still waiting out their backoff. For when the network comes back: the backoff
   * existed because there was no network.
   */
  ignoreBackoff?: boolean;
};

export function createUploader(deps: UploaderDeps) {
  const now = deps.now ?? Date.now;
  let running: Promise<void> | null = null;
  let again = false;
  let deadline: number | undefined;
  let ignoreBackoff = false;

  async function putAll(m: PendingMedia, urls: { original: string; thumb: string }) {
    const files = [
      { uri: m.originalUri, url: urls.original, contentType: m.type === "video" ? "video/mp4" : "image/jpeg" },
      { uri: m.thumbUri, url: urls.thumb, contentType: "image/jpeg" },
    ];
    for (const f of files) {
      let status: number;
      try {
        status = await deps.putFile(f.uri, f.url, f.contentType);
      } catch {
        throw new PutFailed(0);
      }
      if (status < 200 || status >= 300) throw new PutFailed(status);
    }
  }

  /** Uploads an item end to end. Throws if anything fails. */
  async function send(m: PendingMedia, token: string) {
    const api = createApiClient({ baseUrl: deps.apiUrl, token });
    const register = () =>
      unwrap(
        api.POST("/trips/{tripId}/media", {
          params: { path: { tripId: m.tripId } },
          body: {
            id: m.id,
            type: m.type,
            takenAt: m.takenAt,
            lat: m.lat,
            lng: m.lng,
            accuracyM: m.accuracyM,
            caption: m.caption,
            durationS: m.durationS,
            width: m.width,
            height: m.height,
            sizeBytes: m.sizeBytes,
            thumbhash: m.thumbhash,
          },
        }),
      );

    let registered = await register();
    if ("upload" in registered) {
      try {
        await putAll(m, registered.upload);
      } catch (e) {
        // Expired URL: the server gives new URLs for the same id.
        if (!(e instanceof PutFailed && e.status === 403)) throw e;
        registered = await register();
        if ("upload" in registered) await putAll(m, registered.upload);
      }
      if ("upload" in registered) {
        try {
          await unwrap(api.POST("/media/{mediaId}/complete", { params: { path: { mediaId: m.id } } }));
        } catch (e) {
          throw e instanceof ApiError ? new CompleteFailed(e) : e;
        }
      }
    }
  }

  /** Permanent failure: it is marked and reported, because it stops counting as pending. */
  async function discard(m: PendingMedia, reason: string) {
    await deps.queue.markFailed(m.id, reason);
    await deps.onDiscarded?.(m.tripId);
  }

  async function pass() {
    const skipBackoff = ignoreBackoff;
    ignoreBackoff = false;
    const due = (await deps.queue.pending()).filter((m) => skipBackoff || m.retryAt === null || m.retryAt <= now());
    for (const m of due) {
      if (deadline !== undefined && now() >= deadline) return;
      try {
        const token = await deps.getToken(m.tripId);
        if (!token) {
          await discard(m, "no_token");
          continue;
        }
        if (!(await deps.fileExists(m.originalUri)) || !(await deps.fileExists(m.thumbUri))) {
          await discard(m, "missing_file");
          continue;
        }
        await send(m, token);
      } catch (e) {
        const phase: Phase = e instanceof CompleteFailed ? "complete" : "register";
        // An error we can't classify is retried: it never aborts the pass or blocks the queue.
        const verdict = classify(e instanceof CompleteFailed ? e.cause : e, phase) ?? { kind: "retry" };
        if (verdict.kind === "failed") {
          await discard(m, verdict.reason);
          continue;
        }
        if (!(e instanceof PutFailed || e instanceof ApiError || e instanceof CompleteFailed)) {
          console.warn("Error inesperado al subir", m.id, e);
        }
        await deps.queue.markAttempt(m.id, now() + retryDelay(m.attempts + 1));
        if (verdict.kind === "offline") return;
        continue;
      }
      await deps.queue.remove(m.id);
      await deps.removeFiles(m.id);
      await deps.onUploaded?.(m.tripId);
    }
  }

  async function loop() {
    do {
      again = false;
      await pass();
    } while (again);
  }

  return {
    /**
     * Uploads what is pending. Runs one at a time: if a run is already going, requests another pass
     * when it finishes (in case something was enqueued meanwhile) and waits for the current one.
     * The deadline only applies to the run that starts the loop.
     */
    run(options: RunOptions = {}): Promise<void> {
      if (options.ignoreBackoff) ignoreBackoff = true;
      if (running) {
        again = true;
        return running;
      }
      deadline = options.deadline;
      running = loop().finally(() => {
        running = null;
      });
      return running;
    },
  };
}

/** Confirmation error: handled differently from registration ones (see `classify`). */
class CompleteFailed extends Error {
  constructor(public readonly cause: ApiError) {
    super(cause.message);
  }
}
